def backfill_usage(apps, schema_editor):
    """Meter the history the workspace already has, from the runs still
    stored: executions per UTC day, split by project and trigger, and each
    such day's projects as those that existed by then and still exist. Runs
    and projects deleted before metering began are gone, so history can only
    undercount."""
    from datetime import timezone

    StandardExecution = apps.get_model("app", "StandardExecution")
    Project = apps.get_model("app", "Project")
    WorkspaceUsageDay = apps.get_model("app", "WorkspaceUsageDay")
    ExecutionUsage = apps.get_model("app", "ExecutionUsage")

    slices = list(
        StandardExecution.objects.annotate(day=TruncDate("created_at", tzinfo=timezone.utc))
        .values("project__tenant_id", "project_id", "project__name", "event_type", "day")
        .annotate(runs=Count("id"))
    )
    ExecutionUsage.objects.bulk_create(
        [
            ExecutionUsage(
                tenant_id=row["project__tenant_id"],
                day=row["day"],
                project_id=row["project_id"],
                project_name=row["project__name"],
                trigger=row["event_type"] or "manual",
                executions=row["runs"],
            )
            for row in slices
        ],
        ignore_conflicts=True,
    )

    totals = {}
    for row in slices:
        key = (row["project__tenant_id"], row["day"])
        totals[key] = totals.get(key, 0) + row["runs"]
    created = {}
    for tenant_id, at in Project.objects.values_list("tenant_id", "created_at"):
        created.setdefault(tenant_id, []).append(at.astimezone(timezone.utc).date())
    WorkspaceUsageDay.objects.bulk_create(
        [
            WorkspaceUsageDay(
                tenant_id=tenant_id,
                day=day,
                executions=runs,
                peak_projects=sum(d <= day for d in created.get(tenant_id, [])),
            )
            for (tenant_id, day), runs in totals.items()
        ],
        ignore_conflicts=True,
    )



